INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('accuracy','Accuracy','metric','The share of predictions that are correct; misleading when classes are imbalanced.',2,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('addition-rule','Addition Rule','principle','When alternatives are mutually exclusive, the number of outcomes is the sum of the counts.',2,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('antiderivative','Antiderivative','definition','A function whose derivative is the given function; differentiation run backwards.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('applications-of-definite-integral','Applications of the Definite Integral','method','Using integration to compute areas, volumes, lengths and accumulated quantities.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('artificial-neuron','Artificial Neuron','definition','A unit computing a weighted sum of inputs followed by a non-linear activation.',3,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('averaging-and-voting','Averaging and Majority Vote','method','The simplest combination rules: average the predicted numbers, or take the most frequent predicted class.',3,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('backpropagation','Backpropagation','method','Computing the gradient of the loss with respect to every weight by applying the chain rule backwards through the layers.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('bagging','Bagging','method','Training each member on a bootstrap resample to decorrelate their errors and cut variance.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('baseline','Baseline','principle','The trivial predictor any real model must beat before its score means anything.',2,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('bayes-rule','Bayes'' Rule','principle','The formula inverting a conditional probability, turning likelihood and prior into posterior.',4,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('big-o-notation','Big-O Notation','definition','A notation bounding a function''s growth from above up to a constant factor, used to compare rates of change.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('boosting','Adaptive Boosting','method','Fitting members in sequence, each concentrating on the examples its predecessors got wrong.',5,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('cardinality-of-finite-set','The Number of Elements in a Finite Set','principle','Counting a finite set, including the inclusion–exclusion correction for overlapping parts.',2,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('cartesian-product','Cartesian Product','definition','The set of all ordered pairs drawn from two sets, the formal model of independent choices.',2,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('cauchy-mean-value-theorem','Cauchy Mean Value Theorem','principle','A two-function generalisation of the mean value theorem, the basis for L''Hôpital''s rule.',4,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('classification','Classification','method','Supervised prediction of a discrete class label.',2,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('coefficient-matrix','Matrix of a System of Linear Equations','definition','The matrix that holds the coefficients of an SLE, optionally augmented with the right-hand side column, so that the system can be manipulated as a single object instead of as separate equations.',2,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('combination','Combination','definition','A selection of objects where order does not matter; the binomial coefficient counts them.',3,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('combinatorial-probability','Combinatorics in Probability Problems','method','Computing probabilities of equally likely outcomes by counting favourable and total cases.',3,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('conditional-probability','Conditional Probability','definition','The probability of an event given that another has occurred, obtained by restricting the event space.',3,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('confusion-matrix','Confusion Matrix','tool','The table of predicted against actual classes, from which most classification metrics are derived.',2,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('continuity','Continuity on a Closed Interval','definition','A function is continuous on a closed interval when small changes of argument produce small changes of value throughout it, which guarantees strong global properties.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('convergence-of-series','Convergence of a Series','definition','A series converges when its partial sums approach a finite limit.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('convergence-tests','Tests for Convergence','method','The standard criteria — comparison, ratio, root, integral — for deciding convergence without summing.',4,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('convergent-sequence','Convergent Sequence','definition','A sequence that has a finite limit; such sequences are bounded and their limits respect arithmetic.',2,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('convexity','Convexity','definition','A function is convex when its graph lies below its chords; convexity is what makes minimisation well behaved.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('convolution-operation','Convolutional Operation','method','Sliding a shared small filter across the input so that the same local pattern is detected anywhere.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('cross-validation','Cross-Validation','method','Rotating the held-out fold over the data to get a more stable performance estimate.',3,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('curse-of-dimensionality','The Curse of Dimensionality','principle','In high dimensions data becomes sparse and distances lose contrast, undermining methods that rely on proximity.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('data-augmentation','Data Augmentation','method','Enlarging the training set with label-preserving transformations of existing examples.',3,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('data-compression','Data Compression','method','Representing data with fewer numbers while preserving what matters.',3,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('dbscan','DBSCAN','method','Density-based clustering that finds arbitrarily shaped clusters and labels sparse points as noise.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('decision-tree','Decision Tree','method','A predictor that splits the feature space by recursive threshold questions.',2,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('deep-learning','Deep Learning','definition','Learning with many-layered networks that build their own representations of the input.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('definite-integral','Definite Integral','definition','A number attached to a function on an interval, interpretable as signed area under its graph.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('derivative','Derivative','definition','The instantaneous rate of change of a function, defined as the limit of its difference quotient.',2,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('determinant','Determinant','definition','A single number computed from a square matrix that reports whether the matrix is invertible: a zero determinant means the transformation collapses space and cannot be undone.',4,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('determinant-geometric-interpretation','Geometric Meaning of the Determinant','principle','For a 2×2 matrix the determinant is the signed area of the parallelogram spanned by its columns, so its magnitude is the area scaling factor and its sign records whether orientation is flipped.',4,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('differentiable-function','Differentiable Function','definition','A function possessing a derivative at every point of an interval; differentiability implies continuity.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('differential','Differential of a Function','definition','The linear part of a function''s increment, the formal expression of local linear approximation.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('differentiation-rules','Differentiation Rules','method','The algebraic rules — sum, product, quotient and chain — that let derivatives be computed without returning to the limit.',2,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('domain-of-convergence','Domain of Convergence','definition','The set of arguments for which a power series converges.',4,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('dropout','Dropout','method','Randomly disabling units during training so the network cannot rely on any single path.',3,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('elementary-row-operations','Elementary Row Operations','method','The three reversible moves on a matrix — swapping two rows, scaling a row by a non-zero number, and adding a multiple of one row to another — that change the matrix without changing the solution set of the system it represents.',2,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('ensemble-learning','Ensemble Learning','framework','Combining several models so their errors partly cancel and the whole beats any part.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('epsilon-delta-definition','Cauchy (ε–δ) Definition of a Limit','definition','The formal definition: for every ε there is a δ such that arguments within δ of the point map to values within ε of the limit.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('euler-diagram','Euler Diagram','tool','A picture of sets as regions, used to reason about their overlaps.',1,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('event','Event','definition','A subset of the event space, so that operations on events are operations on sets.',2,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('event-space','Event Space','definition','The set of all possible outcomes of an experiment, the universe in which probability is defined.',2,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('expected-value','Expected Value','metric','The probability-weighted average of a random variable, its long-run mean.',3,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('f1-score','F1 / Dice Score','metric','The harmonic mean of precision and recall, a single number balancing the two.',3,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('feedforward-network','Feed-Forward Network','framework','A network of neuron layers passing signals in one direction from input to output.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('function-graphing','Graphing Functions','method','Assembling limits, derivatives and convexity into a full qualitative picture of a function''s graph.',2,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('gaussian-elimination','Jordan–Gauss Method (Gaussian Elimination)','method','The systematic procedure of applying elementary row operations to bring a matrix to row-echelon form, and thereby to solve a system of linear equations by a fixed algorithm rather than ad-hoc tricks.',2,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('geometric-transformation-matrix','Geometric Transformations as Matrices','framework','The correspondence between matrices and geometric motions of the plane: applying a matrix to the coordinate vectors of a figure moves the figure, so composing motions becomes multiplying matrices.',4,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('heine-definition','Heine (Sequential) Definition of a Limit','definition','An equivalent definition of a function limit stated through the limits of all sequences approaching the point.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('hierarchical-clustering','Hierarchical Clustering','method','Building a nested tree of clusters by repeatedly merging or splitting groups.',3,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('higher-order-derivative','Higher-Order Derivative','definition','The result of differentiating repeatedly; the second derivative measures curvature.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('holistic-evaluation','Holistic View of Evaluation','principle','Judging a model by the whole picture of metrics, baselines and error structure rather than one score.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('improper-integral','Improper Integral','definition','An integral over an unbounded interval or of an unbounded function, defined as a limit of ordinary integrals.',4,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('indefinite-integral','Indefinite Integral','definition','The family of all antiderivatives of a function, differing by a constant.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('independent-events','Independent Events','definition','Events where knowing one occurred does not change the probability of the other.',3,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('integration-by-parts','Integration by Parts','method','Trading one integral for another using the product rule in reverse.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('integration-by-substitution','Integration by Substitution','method','Changing variable in an integral so that it matches a known antiderivative; the chain rule reversed.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('intermediate-value-theorem','Cauchy''s Intermediate Value Theorem','principle','A function continuous on a closed interval attains every value between its endpoint values.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('inverse-2x2-formula','Explicit Inverse Formula for a 2×2 Matrix','method','The closed-form expression that gives the inverse of a 2×2 matrix directly from its four entries and its determinant, with no elimination needed.',3,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('inverse-matrix','Inverse Matrix','definition','The matrix that undoes another: multiplying a matrix by its inverse gives the identity. It exists only for square matrices that are non-degenerate.',4,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('inverse-via-jordan-gauss','Finding an Inverse by the Jordan–Gauss Method','method','Computing an inverse by row-reducing the matrix alongside the identity until the original becomes the identity and the identity becomes the inverse.',4,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('k-means','K-Means','method','Partitioning data into k clusters by alternately assigning points to nearest centroids and recomputing them.',3,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('knn','K-Nearest Neighbours','method','Predicting from the labels of the closest training examples, with no explicit training step.',2,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('l1-regularization','L1 Regularization','method','Penalising the sum of absolute weights, which drives some exactly to zero and selects features.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('l2-regularization','L2 Regularization','method','Penalising the sum of squared weights, shrinking them smoothly toward zero.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('lagrange-mean-value-theorem','Lagrange Mean Value Theorem','principle','On any interval a differentiable function has a point whose derivative equals the average rate of change across the interval.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('lhopitals-rule','L''Hôpital''s Rule','method','A technique for evaluating indeterminate limits by differentiating numerator and denominator separately.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('limit-of-function','Limit of a Function at a Point','definition','The value a function approaches as its argument approaches a given point, independently of the value at that point.',2,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('limit-of-sequence','Limit of a Sequence','definition','The value a sequence approaches arbitrarily closely as the index grows without bound.',2,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('linear-equation','Linear Equation','definition','An equation in which every unknown appears only to the first power and is not multiplied by another unknown. It is the atom the whole course is built from.',1,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('linear-model-thinking','Thinking in Terms of Linear Models','principle','The habit the course is ultimately aiming at: recognising when a situation with many quantities changing at once can be posed and solved linearly, rather than memorising procedures.',2,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('linear-regression','Linear Regression','method','Fitting a linear function of the features by minimising squared error.',2,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('linear-space','Linear Space (Vector Space)','definition','The abstract setting in which addition and scalar multiplication obey a fixed list of rules; recognising it is what lets the same reasoning transfer from arrows to data tables to functions.',3,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('little-o-notation','Little-o Notation','definition','A notation stating that one function is asymptotically negligible relative to another.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('logical-operations','Logical Operations','method','Negation, conjunction, disjunction and implication, which combine propositions into compound statements.',1,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('logical-proposition','Logical Proposition','definition','A statement that is definitely either true or false, the atom of formal reasoning.',1,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('maclaurin-series','Maclaurin Series','definition','The Taylor series taken at zero.',4,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('matrix','Matrix','definition','A rectangular table of numbers arranged in rows and columns, used to store coefficients, data sets or transformations compactly.',1,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('matrix-addition','Matrix Addition','method','Adding two matrices of identical dimensions entry by entry.',3,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('matrix-modelling','Modelling Real Situations with Vectors and Matrices','method','The practice of translating a real problem — a small economic balance, a data-analysis task — into vectors and matrices so that it becomes a solvable system.',3,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('matrix-multiplication','Matrix Multiplication','method','Combining two matrices into a third whose entries are dot products of rows with columns; it corresponds to performing one transformation after another and is not commutative.',3,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('matrix-transposition','Matrix Transposition','method','Reflecting a matrix across its main diagonal so that rows become columns; the operation behind symmetric matrices and many identities.',3,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('matrix-vector-multiplication','Matrix–Vector Multiplication','method','Applying a matrix to a vector to obtain a new vector; this is the operation that turns a matrix into a transformation and lets an SLE be written as a single equation.',3,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('mean-value-theorem-for-integrals','Mean Value Theorem for Integrals','principle','A continuous function attains its average value over an interval at some interior point.',4,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('multiplication-rule','Multiplication Rule','principle','When choices are made in sequence, the number of outcomes is the product of the counts.',2,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('negation-of-claim','Building Negations to Claims','method','Turning a statement, including quantified ones, into its correct denial — the skill behind complementary events.',2,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('newton-leibniz-formula','Newton–Leibniz Formula','principle','The fundamental link: a definite integral equals the increment of any antiderivative across the interval.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
