INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('one-sided-limit','One-Sided Limit','definition','The limit taken as the argument approaches a point from only the left or only the right.',2,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
