INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('regularization','Regularization','principle','Deliberately constraining a model to reduce overfitting at the cost of some training fit.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('roc-auc','ROC / AUC','metric','The curve of true against false positive rates over all thresholds, and the area beneath it.',4,'machine-learning','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('rolles-theorem','Rolle''s Theorem','principle','A function continuous on a closed interval, differentiable inside it and equal at the endpoints has a stationary point strictly inside.',3,'calculus','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('rotation','Rotation','method','A transformation turning the plane about a point by a fixed angle, expressible as a matrix built from sine and cosine.',4,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('row-echelon-form','Row-Echelon Form','definition','A staircase shape for a matrix in which each leading entry sits strictly to the right of the one above it, making the solution of the corresponding system readable almost directly.',2,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('scalar-multiplication','Scalar Multiplication','method','Multiplying every entry of a vector or matrix by the same number, which stretches, shrinks or flips it without changing its shape.',3,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('scaling','Scaling','method','A transformation stretching or shrinking the plane along its axes, the simplest case of a matrix acting geometrically.',3,'linear-algebra','llm',0.8) ON CONFLICT (slug) DO NOTHING;
