INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('set','Set','definition','A collection of distinct objects considered as one whole.',1,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO concepts (slug,name,kind,definition,difficulty,domain,provenance,confidence) VALUES ('set-operations','Set Operations','method','Union, intersection, difference and complement, the operations mirrored later by operations on events.',2,'probability','llm',0.8) ON CONFLICT (slug) DO NOTHING;
